**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than (`<`), so when `exp === floor(now)` the condition is false and the expired token passes. Fix: use `<=`.

**Larger issue:** `jwt.verify()` already checks expiration internally — the manual `exp` check is redundant and error-prone. The real gaps are: (1) the off-by-one shown above, and (2) the catch block swallows all errors with the same generic message, hiding token-expired cases from callers.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify() handles expiry correctly (rejects exp <= now),
    // so no manual exp check needed.
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // NotBeforeError or unexpected errors
    return res.status(401).json({ error: 'Token not accepted' });
  }
}

module.exports = authMiddleware;
```

**What changed:**
- Removed the manual `exp` check — `jwt.verify()` rejects tokens where `exp <= now` (boundary-inclusive), which is the correct behavior
- Split catch into `TokenExpiredError` / `JsonWebTokenError` / fallback so clients get actionable error messages and you can log unexpected errors separately if needed
